(window.SkillzifyLessonContent = window.SkillzifyLessonContent || {})["launch-pad"] = [{"id":"a26","section":"launch-pad","track":"advanced","title":"SQLite Databases with Python","explain":"The sqlite3 module is in the standard library and stores a full SQL database in one file — or in RAM with :memory:. Always use ? placeholders for values; never format them into SQL strings yourself.","takeaways":["sqlite3.connect(':memory:') gives you a throwaway database for experiments.","Use ? placeholders to prevent SQL injection.","commit() persists writes; close connections with a context manager or try/finally."],"code":"import sqlite3\n\ndb = sqlite3.connect(\":memory:\")\ndb.execute(\"CREATE TABLE users (name TEXT, age INTEGER)\")\ndb.executemany(\"INSERT INTO users VALUES (?, ?)\", [(\"Ava\", 30), (\"Bo\", 25)])\ndb.commit()\nrows = db.execute(\"SELECT name FROM users WHERE age > 26 ORDER BY name\").fetchall()\nprint(rows)\ndb.close()","quiz":[{"q":"Why use ? placeholders instead of f-strings in SQL?","options":["To prevent SQL injection attacks","They are faster to type","f-strings cannot be used with SQL","Placeholders are required by law"],"answer":0,"why":"The driver safely escapes bound values; string formatting lets attackers inject SQL."},{"q":"What does commit() do?","options":["Persists pending writes to the database","Deletes the table","Opens a new connection","Prints the schema"],"answer":0,"why":"Writes sit in a transaction until committed."},{"q":"What is sqlite3.connect(':memory:')?","options":["A temporary database kept in RAM","A connection to a remote server","A read-only database file","An error"],"answer":0,"why":":memory: is the special name for a private in-RAM database."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"import sqlite3\ndb = sqlite3.connect(\":memory:\")\ndb.execute(\"CREATE TABLE t (v INTEGER)\")\ndb.executemany(\"INSERT INTO t VALUES (?)\", [(1,), (2,), (3,)])\nn = db.execute(\"SELECT SUM(v) FROM t\").fetchone()[0]\nprint(n)","options":["6","123","(6,)","Error"],"answer":0,"hint":"fetchone() returns one row tuple; [0] takes its first column."}},{"id":"a27","section":"launch-pad","track":"advanced","title":"Talking to APIs: requests & JSON","explain":"The requests library turns HTTP into one-liners: requests.get(url).json() fetches a URL and parses the JSON body. Always set a timeout, check the status code, and parse defensively since APIs change shape.","takeaways":["requests.get(url, timeout=10).json() is the core API-call pattern.","Always set a timeout and check response.status_code before trusting the body.","Parse defensively with .get() and defaults: API responses change."],"code":"import json\n\n# this is what requests.get(url).json() would hand you:\nsample = '{\"name\": \"Skillzify\", \"users\": 1200, \"tags\": [\"python\", \"learn\"]}'\ndata = json.loads(sample)\nprint(data[\"name\"], data[\"users\"])\nprint(data[\"tags\"][1].upper())","quiz":[{"q":"What does requests.get(url).json() do?","options":["Fetches the URL and parses the response body as JSON","Downloads a file to disk","Sends JSON data to the server","Opens the URL in a browser"],"answer":0,"why":".json() decodes the response bytes into Python objects."},{"q":"Why pass timeout=10 to requests.get?","options":["So a hung server cannot freeze your program forever","It makes the server respond faster","It is required for JSON responses","It enables response caching"],"answer":0,"why":"Without a timeout, a dead server can block your call indefinitely."},{"q":"How should you read a possibly-missing key from API JSON?","options":["data.get('key') with a sensible default","data['key'] and hope for the best","eval() on the raw text","Assume the key always exists"],"answer":0,"why":".get() avoids KeyError when the API shape drifts."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"import json\nraw = '{\"items\": [{\"id\": 1}, {\"id\": 2}, {\"id\": 3}]}'\ndata = json.loads(raw)\nprint(len(data[\"items\"]), data[\"items\"][-1][\"id\"])","options":["3 3","3 2","2 3","Error"],"answer":0,"hint":"Three dicts in the list; [-1] is the last one, whose id is 3."}},{"id":"a29","section":"launch-pad","track":"advanced","title":"Capstone: argparse CLI Application","explain":"argparse turns a script into a real command-line tool: positional arguments, --flags, help text, and type conversion come free. parse_args() reads sys.argv, but you can pass an explicit list when testing.","takeaways":["add_argument defines positionals ('name') and optionals ('--shout').","type=int converts input; action='store_true' makes boolean flags.","--help is generated automatically from your help= strings."],"code":"import argparse\n\ndef build_parser():\n    p = argparse.ArgumentParser(description=\"Greet someone\")\n    p.add_argument(\"name\")\n    p.add_argument(\"--shout\", action=\"store_true\")\n    return p\n\nargs = build_parser().parse_args([\"Ava\", \"--shout\"])\nmsg = \"Hello, \" + args.name + \"!\"\nprint(msg.upper() if args.shout else msg)","quiz":[{"q":"What does add_argument('--shout', action='store_true') create?","options":["A boolean flag that is False unless --shout is passed","A required string argument","A subcommand","An environment variable"],"answer":0,"why":"store_true flips the default False to True when the flag appears."},{"q":"How do you test argparse code without real command-line arguments?","options":["parser.parse_args(['Ava', '--shout']) with an explicit list","You cannot: it only ever reads sys.argv","By editing sys.path","With input() prompts"],"answer":0,"why":"parse_args optionally takes the argument list, which makes it testable."},{"q":"What does --help do for an argparse program?","options":["Prints auto-generated usage from your declared arguments","Opens a web browser","Deletes the parser","Nothing at all"],"answer":0,"why":"argparse builds the help screen from your arguments and help= strings."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"import argparse\np = argparse.ArgumentParser()\np.add_argument(\"x\", type=int)\np.add_argument(\"--times\", type=int, default=1)\na = p.parse_args([\"5\", \"--times\", \"3\"])\nprint(a.x * a.times)","options":["15","8","53","Error"],"answer":0,"hint":"x becomes int 5, --times becomes int 3; multiply them."}},{"id":"a63","section":"launch-pad","track":"advanced","title":"Web: HTTP Basics for Python Devs","explain":"HTTP is the language browsers and servers speak: a request line (GET /lessons), headers, and an optional body, answered by a status code and a body — often JSON. You can practise the whole exchange offline by parsing sample responses instead of hitting a real server.","takeaways":["A response starts with a status code: `200` means OK, `404` means not found.","Parse a URL's parts with `urllib.parse.urlparse`: scheme, netloc, path and query.","JSON bodies parse with `json.loads()`; the sample below is exactly what an API would hand you."],"code":"import json\nfrom urllib.parse import urlparse\n\n# this is what requests.get(url).json() would hand you:\nsample = '{\"status\": 200, \"body\": {\"user\": \"Ava\", \"id\": 7}}'\nresp = json.loads(sample)\nprint(resp[\"status\"])\nprint(resp[\"body\"][\"user\"])\nu = urlparse(\"https://example.com/lessons/7?sort=top\")\nprint(u.path)\nprint(u.query)","quiz":[{"q":"What does HTTP status code 200 mean?","options":["Not found","OK: the request succeeded","Server error","Redirect"],"answer":1,"why":"200 is the success code; the server did what you asked."},{"q":"What is the query string in a URL?","options":["The part after ? with key=value pairs","The domain name","The protocol","The page title"],"answer":0,"why":"Everything after the ? is the query string, like sort=top."},{"q":"What is the difference between GET and POST?","options":["GET sends data in the body, POST in the URL","GET fetches data, POST sends data to create or change something","They are identical","POST cannot return JSON"],"answer":1,"why":"GET is for reading, POST carries a body to create or update a resource."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"from urllib.parse import urlparse\nu = urlparse(\"https://skillzify.example/api/users?page=2\")\nprint(u.netloc)","options":["skillzify.example","https","/api/users","page=2"],"answer":0,"hint":"netloc is the network location: the domain (and port, if any)."}},{"id":"a64","section":"launch-pad","track":"advanced","title":"Web: Flask First App","explain":"Flask turns a Python function into a web page: @app.route('/') maps a URL to the function below it, and the function's return value becomes the response. You can test routes with app.test_client() without ever starting a server.","takeaways":["`@app.route('/')` maps a URL path to the function below it.","The view function's return value becomes the HTTP response body.","Use `app.test_client()` to call routes in tests — never `app.run()` in lesson code."],"code":"from flask import Flask\napp = Flask(__name__)\n@app.route(\"/\")\ndef home():\n    return \"Hello, Skillzify!\"\nclient = app.test_client()\nresp = client.get(\"/\")\nprint(resp.status_code)\nprint(resp.data.decode())","quiz":[{"q":"What does @app.route('/') do?","options":["Starts the server","Maps the URL / to the function below it","Creates a database","Imports Flask"],"answer":1,"why":"The decorator registers the view function as the handler for that path."},{"q":"Why use app.test_client() in this lesson?","options":["It exercises routes without starting a real server","It is faster than a browser","It deploys the app","It writes HTML files"],"answer":0,"why":"The test client calls your routes in-process, so no server or port is needed."},{"q":"What does a status_code of 200 mean?","options":["Page not found","The request succeeded","The server crashed","A redirect"],"answer":1,"why":"200 is HTTP for OK — the route ran and returned a response."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"from flask import Flask\napp = Flask(__name__)\n@app.route(\"/hi\")\ndef hi():\n    return \"Hi Ava\"\nprint(app.test_client().get(\"/hi\").data.decode())","options":["Hi Ava","Hi","404","Error"],"answer":0,"hint":"The /hi route returns the string 'Hi Ava' as the response body.","localOnly":true}},{"id":"a65","section":"launch-pad","track":"advanced","title":"Web: Flask Routing & Templates","explain":"Routes can capture parts of the URL: /hello/<name> hands 'Ava' to your function as name. Templates then mix that value into HTML with {{ name }} placeholders, so one route can serve a personalised page for every visitor.","takeaways":["`<name>` in a route captures that URL segment as a function argument.","`<int:n>` captures the segment and converts it to an int automatically.","Render HTML with placeholders using `render_template_string('... {{ name }} ...', name=name)`."],"code":"from flask import Flask, render_template_string\napp = Flask(__name__)\n@app.route(\"/hello/<name>\")\ndef hello(name):\n    return render_template_string(\"<h1>Hello, {{ name }}!</h1>\", name=name)\nclient = app.test_client()\nprint(client.get(\"/hello/Ava\").data.decode())\nprint(client.get(\"/missing\").status_code)","quiz":[{"q":"What does <name> in a route like /hello/<name> do?","options":["It is a comment","It captures that URL segment as a function argument","It sets the page title","It imports a module"],"answer":1,"why":"Flask passes the captured segment into the view function as name."},{"q":"What does render_template_string do?","options":["Renders a template string with {{ }} placeholders filled in","Saves a template to a file","Starts the server","Validates a form"],"answer":0,"why":"It takes a template string plus values and returns the filled-in HTML."},{"q":"What status code does Flask return for an unknown URL?","options":["200","500","404","301"],"answer":2,"why":"404 means no route matched the requested path."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"from flask import Flask\napp = Flask(__name__)\n@app.route(\"/square/<int:n>\")\ndef square(n):\n    return str(n * n)\nprint(app.test_client().get(\"/square/5\").data.decode())","options":["5","10","25","Error"],"answer":2,"hint":"<int:n> converts 5 to the integer 5, and 5 squared is 25.","localOnly":true}},{"id":"a66","section":"launch-pad","track":"advanced","title":"Web: Flask Forms & Validation","explain":"Forms arrive on the server as request.form, a dict-like object of the submitted fields. Always validate there: strip whitespace, reject blanks, and answer bad input with a 400 status — because anyone can bypass the checks in the browser.","takeaways":["Read submitted fields with `request.form.get('name', '')`.","Use `.strip()` so a name of only spaces fails validation like a blank one.","Return a `400` status for invalid input so the client knows the request was bad."],"code":"from flask import Flask, request\napp = Flask(__name__)\n@app.route(\"/signup\", methods=[\"POST\"])\ndef signup():\n    name = request.form.get(\"name\", \"\").strip()\n    if not name:\n        return \"Name is required\", 400\n    return \"Welcome, \" + name\nclient = app.test_client()\nprint(client.post(\"/signup\", data={\"name\": \"Ava\"}).status_code)\nprint(client.post(\"/signup\", data={\"name\": \"\"}).status_code)","quiz":[{"q":"Why validate form input on the server, not just in the browser?","options":["Browsers never send bad data","Anyone can bypass browser checks, so the server is the last line of defence","It makes pages prettier","Flask requires it"],"answer":1,"why":"Browser validation is cosmetic; a crafted request can skip it entirely."},{"q":"What does request.form.get('name', '') do?","options":["Reads the name field, defaulting to an empty string","Deletes the field","Creates a database row","Redirects the user"],"answer":0,"why":"get with a default avoids a KeyError when the field is missing."},{"q":"Why strip() the name before checking it?","options":["To encrypt the name","To sort the name","To remove surrounding spaces so blank-looking input fails validation","To make it lowercase"],"answer":2,"why":"Without strip, a name of three spaces would pass the 'not name' check."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"from flask import Flask, request\napp = Flask(__name__)\n@app.route(\"/signup\", methods=[\"POST\"])\ndef signup():\n    name = request.form.get(\"name\", \"\").strip()\n    if not name:\n        return \"Name is required\", 400\n    return \"Welcome, \" + name\nprint(app.test_client().post(\"/signup\", data={\"name\": \" Bo \"}).data.decode())","options":["Welcome, Bo","Welcome,  Bo ","Name is required","Error"],"answer":0,"hint":"strip() removes the spaces around Bo before the greeting is built.","localOnly":true}},{"id":"a67","section":"launch-pad","track":"advanced","title":"Web: REST APIs with Flask","explain":"A REST API is a set of URLs that speak JSON instead of HTML: GET fetches, POST creates, and each resource has its own path like /api/lessons. jsonify() turns your Python dicts and lists into a proper JSON response.","takeaways":["A REST endpoint returns structured data (usually JSON) over HTTP verbs.","`jsonify(data)` converts Python data into a JSON response.","Use GET to fetch, POST to create, and `request.get_json()` to read a JSON body."],"code":"from flask import Flask, jsonify\napp = Flask(__name__)\nlessons = [{\"id\": 1, \"title\": \"Hello Python\"}]\n@app.route(\"/api/lessons\")\ndef get_lessons():\n    return jsonify(lessons)\nclient = app.test_client()\nresp = client.get(\"/api/lessons\")\nprint(resp.status_code)\nprint(resp.get_json()[0][\"title\"])","quiz":[{"q":"What makes an endpoint a REST API rather than a web page?","options":["It returns HTML pages","It returns structured data like JSON over HTTP verbs","It uses a database","It needs JavaScript"],"answer":1,"why":"APIs exchange data (JSON) while pages return HTML for humans."},{"q":"Which HTTP verb is used to create a new resource?","options":["GET","DELETE","POST","HEAD"],"answer":2,"why":"By convention POST creates, GET reads, PUT/PATCH updates, DELETE removes."},{"q":"What does jsonify() do?","options":["Parses JSON from a request","Converts Python data to a JSON response","Validates a token","Connects to a database"],"answer":1,"why":"jsonify serialises your data and sets the JSON content type."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"from flask import Flask, jsonify, request\napp = Flask(__name__)\n@app.route(\"/api/echo\", methods=[\"POST\"])\ndef echo():\n    return jsonify(request.get_json())\nprint(app.test_client().post(\"/api/echo\", json={\"x\": 3}).get_json())","options":["{'x': '3'}","{'x': 3}","None","Error"],"answer":1,"hint":"The JSON body round-trips: 3 stays the number 3, not the string '3'.","localOnly":true}},{"id":"a68","section":"launch-pad","track":"advanced","title":"Web: FastAPI First App","explain":"FastAPI is a modern framework for building APIs: you declare routes with decorators just like Flask, but return plain Python dicts and FastAPI turns them into JSON. It also generates interactive docs at /docs from your routes, for free.","takeaways":["Declare routes with `@app.get('/hello')` and return a dict — FastAPI serialises it to JSON.","Test without a server using `TestClient(app)`, the same idea as Flask's test client.","FastAPI builds interactive API docs at `/docs` automatically from your code."],"code":"from fastapi import FastAPI\nfrom fastapi.testclient import TestClient\napp = FastAPI()\n@app.get(\"/hello\")\ndef hello():\n    return {\"message\": \"Hello, Ava\"}\nclient = TestClient(app)\nresp = client.get(\"/hello\")\nprint(resp.status_code)\nprint(resp.json()[\"message\"])","quiz":[{"q":"What does FastAPI give you over a plain Flask API?","options":["Automatic docs and data validation from type hints","A built-in database","Free hosting","It only works with JavaScript"],"answer":0,"why":"FastAPI generates OpenAPI docs and validates requests from your type hints."},{"q":"What does the /docs page show?","options":["Your source code","Interactive API docs generated from your routes","Server logs","The database contents"],"answer":1,"why":"FastAPI builds a Swagger UI page from your routes, where you can try each endpoint."},{"q":"What does a FastAPI view function returning a dict produce?","options":["A JSON response","An HTML page","A file download","An error"],"answer":0,"why":"FastAPI serialises returned dicts to JSON automatically."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"from fastapi import FastAPI\nfrom fastapi.testclient import TestClient\napp = FastAPI()\n@app.get(\"/square/{n}\")\ndef square(n: int):\n    return {\"result\": n * n}\nprint(TestClient(app).get(\"/square/6\").json())","options":["{'result': 36}","{'result': '36'}","{'result': 6}","Error"],"answer":0,"hint":"The path parameter n: int converts '6' to 6, and 6 squared is 36.","localOnly":true}},{"id":"a69","section":"launch-pad","track":"advanced","title":"Web: Authentication Basics (Sessions & Tokens)","explain":"Authentication answers 'who are you?' — usually by checking a password against a stored hash, never the password itself. Once logged in, the server remembers you with a session or hands you a token to send with each request.","takeaways":["Store password hashes, never plain passwords — `hashlib.sha256` turns a password into a fixed fingerprint.","Compare hashes with `hmac.compare_digest` to avoid timing attacks.","A session remembers a logged-in user server-side; a token is a credential the client sends with each request."],"code":"import hashlib, hmac\nstored = hashlib.sha256(\"correct-horse\".encode()).hexdigest()\nattempt = hashlib.sha256(\"correct-horse\".encode()).hexdigest()\nprint(hmac.compare_digest(stored, attempt))\nprint(hmac.compare_digest(stored, hashlib.sha256(\"wrong\".encode()).hexdigest()))","quiz":[{"q":"Why store a password hash instead of the password itself?","options":["Hashes are shorter","A stolen database then does not reveal passwords directly","It is faster to log in","Passwords cannot be stored at all"],"answer":1,"why":"A hash cannot be reversed into the password, so a leak is far less damaging."},{"q":"What is a session?","options":["A server-side record that remembers a logged-in user across requests","A browser tab","A password hash","A database table"],"answer":0,"why":"The session id in a cookie points at server-side state for that user."},{"q":"How should a client send an auth token?","options":["In the URL of every link","In an Authorization header or a secure cookie","Printed on the page","In a public comment"],"answer":1,"why":"Headers and secure cookies keep the token out of URLs, logs and page text."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"import hashlib\nprint(hashlib.sha256(b\"abc\").hexdigest()[:6])","options":["e3b0c4","ba7816","abc123","Error"],"answer":1,"hint":"sha256 of 'abc' is a famous test vector — it starts with ba7816."}},{"id":"a70","section":"launch-pad","track":"advanced","title":"Web: Talking to Databases (SQLAlchemy Intro)","explain":"SQLAlchemy is Python's standard ORM: you describe a table as a class, and the ORM writes the SQL for you. An engine connects to the database, Base.metadata.create_all() builds the tables, and a Session is where you add, commit and query rows.","takeaways":["An ORM maps classes to tables: a `User` class becomes a `users` table.","`create_engine('sqlite:///:memory:')` opens an in-memory SQLite database.","Add objects to a `Session`, call `commit()` to save them, and query with `select(User)`."],"code":"from sqlalchemy import Column, Integer, String, create_engine, select\nfrom sqlalchemy.orm import declarative_base, Session\nBase = declarative_base()\nclass User(Base):\n    __tablename__ = \"users\"\n    id = Column(Integer, primary_key=True)\n    name = Column(String)\nengine = create_engine(\"sqlite:///:memory:\")\nBase.metadata.create_all(engine)\nwith Session(engine) as s:\n    s.add(User(name=\"Ava\"))\n    s.commit()\n    print(s.execute(select(User)).scalars().all()[0].name)\n    print(len(s.execute(select(User)).scalars().all()))","quiz":[{"q":"What does an ORM like SQLAlchemy do?","options":["It writes raw SQL for you by mapping classes to tables","It hosts your database server","It encrypts passwords","It replaces Python"],"answer":0,"why":"You work with Python objects and the ORM translates to SQL."},{"q":"What does create_engine('sqlite:///:memory:') create?","options":["A file database","An in-memory SQLite database that vanishes when the program ends","A PostgreSQL server","A CSV file"],"answer":1,"why":":memory: means the whole database lives in RAM and disappears on exit."},{"q":"What does session.commit() do?","options":["Deletes all rows","Closes the connection","Creates the tables","Saves pending changes to the database"],"answer":3,"why":"Until commit, added objects are only staged; commit writes them durably."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"from sqlalchemy import Column, Integer, String, create_engine, select\nfrom sqlalchemy.orm import declarative_base, Session\nBase = declarative_base()\nclass User(Base):\n    __tablename__ = \"users\"\n    id = Column(Integer, primary_key=True)\n    name = Column(String)\nengine = create_engine(\"sqlite:///:memory:\")\nBase.metadata.create_all(engine)\nwith Session(engine) as s:\n    s.add_all([User(name=\"Ava\"), User(name=\"Bo\")])\n    s.commit()\n    print(len(s.execute(select(User)).scalars().all()))","options":["1","0","2","Error"],"answer":2,"hint":"Two users are added and committed, so the query returns two rows.","localOnly":true}},{"id":"a71","section":"launch-pad","track":"advanced","title":"Automation: Scripting Your OS with os & shutil","explain":"Automation starts with the operating system: listing files, copying them, and tidying folders without clicking around. The os and shutil modules give you those superpowers in a few lines, and a script can repeat the job perfectly a thousand times.","takeaways":["`os.listdir('.')` lists files in the current folder; `os.path.exists(path)` checks a file is really there.","`shutil.copy(src, dst)` copies a file; `shutil.move(src, dst)` moves or renames it.","`os.makedirs(path, exist_ok=True)` creates folders without crashing if they already exist."],"code":"import os, shutil\n\nopen(\"demo.txt\", \"w\").write(\"hello automation\")\nshutil.copy(\"demo.txt\", \"demo_backup.txt\")\nprint(\"backup exists:\", os.path.exists(\"demo_backup.txt\"))\nprint(\"size:\", os.path.getsize(\"demo.txt\"))\nprint(\"txt files:\", sorted(f for f in os.listdir(\".\") if f.startswith(\"demo\")))","quiz":[{"q":"What does shutil.copy('a.txt', 'b.txt') do?","options":["Deletes a.txt after copying it","Renames the folder containing a.txt","Prints the contents of a.txt","Copies the file a.txt to a new file b.txt"],"answer":3,"why":"copy duplicates the file; the original stays exactly where it was."},{"q":"Why use os.makedirs('logs', exist_ok=True) instead of os.mkdir('logs')?","options":["It works only on Windows","It creates nested folders and does not crash if the folder already exists","It is faster for large files","It deletes old files in the folder"],"answer":1,"why":"makedirs builds parent folders too, and exist_ok=True makes a repeat run safe."},{"q":"What does os.path.getsize('demo.txt') return?","options":["The number of lines in the file","The date the file was created","The folder the file lives in","The size of the file in bytes"],"answer":3,"why":"getsize reports the file size in bytes."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"import os\nos.makedirs(\"logs\", exist_ok=True)\nopen(\"logs/a.txt\", \"w\").write(\"x\")\nprint(os.path.isdir(\"logs\"), os.path.exists(\"logs/a.txt\"))","options":["True False","False True","Error","True True"],"answer":3,"hint":"makedirs creates the folder, and the file is written inside it."}},{"id":"a72","section":"launch-pad","track":"advanced","title":"Automation: Web Scraping Basics","explain":"Web scraping means pulling useful data out of a web page: titles, prices, links. You fetch the HTML, then search it for patterns — and you must respect robots.txt, rate limits, and the site's terms before scraping anything real.","takeaways":["HTML is just text, so `re.findall(r'<h2>(.*?)</h2>', html)` can pull out every heading.","Always check robots.txt and the site terms, and scrape politely with delays between requests.","For real pages, prefer an official API; scrape only when no API exists."],"code":"import re\n\n# sample HTML, like the body a requests call would hand you:\nsample = \"<html><body><h2>Python Tips</h2><h2>Flask Guide</h2><p>Price: $25</p></body></html>\"\ntitles = re.findall(r\"<h2>(.*?)</h2>\", sample)\nprice = re.search(r\"\\$(\\d+)\", sample).group(1)\nprint(titles)\nprint(\"price:\", price)","quiz":[{"q":"What does re.findall(r'<h2>(.*?)</h2>', html) return?","options":["A list of the text inside every <h2> tag","The whole HTML page as one string","Only the first heading on the page","A list of all the links on the page"],"answer":0,"why":"findall returns every non-overlapping match of the pattern."},{"q":"Before scraping a real website, what should you check first?","options":["Whether the site uses JavaScript","The number of images on the page","Its robots.txt and terms of use","The colour scheme of the homepage"],"answer":2,"why":"robots.txt and the terms say what automated access the site allows."},{"q":"Why is scraping every second without a delay a bad idea?","options":["It can overload the server and get your IP blocked","It makes the HTML invalid","It breaks the re module","It deletes the page from the server"],"answer":0,"why":"Rapid-fire requests look like an attack; polite scrapers pause between requests."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"import re\nsample = \"<ul><li>Ava</li><li>Bo</li></ul>\"\nitems = re.findall(r\"<li>(.*?)</li>\", sample)\nprint(len(items), items[0])","options":["Error","2 Ava","2 Bo","1 Ava"],"answer":1,"hint":"Count the <li> pairs, then take the first match."}},{"id":"a73","section":"launch-pad","track":"advanced","title":"Automation: Working with Excel Files (openpyxl)","explain":"openpyxl lets Python read and write real .xlsx spreadsheets: build reports, fill in scores, or pull numbers out of a sheet someone emailed you. A workbook holds sheets, sheets hold cells, and you address cells like ws['B2'].","takeaways":["`openpyxl.Workbook()` creates a workbook; `wb.active` is its first sheet.","`ws.append([\"Ava\", 92])` adds a whole row at the bottom of the sheet.","`openpyxl.load_workbook(\"scores.xlsx\")` re-opens a saved file for reading."],"code":"import openpyxl\n\nwb = openpyxl.Workbook()\nws = wb.active\nws.title = \"Scores\"\nws.append([\"Name\", \"Score\"])\nws.append([\"Ava\", 92])\nws.append([\"Bo\", 78])\nwb.save(\"scores.xlsx\")\nwb2 = openpyxl.load_workbook(\"scores.xlsx\")\nws2 = wb2[\"Scores\"]\nprint(ws2[\"A2\"].value, ws2[\"B2\"].value)\nprint(ws2.max_row)","quiz":[{"q":"What does ws.append(['Ava', 92]) do?","options":["Deletes the last row of the sheet","Adds a new row with Ava in column A and 92 in column B","Adds a new sheet named Ava","Sorts the sheet by score"],"answer":1,"why":"append writes the list as the next empty row, one value per column."},{"q":"How do you read the value in cell B2 after loading a workbook?","options":["ws.B2()","wb.read('B2')","ws.cell_value(2)","ws['B2'].value"],"answer":3,"why":"Cells are addressed like ws['B2'], and .value holds the contents."},{"q":"What does ws.max_row tell you?","options":["The width of the widest column","The number of the last row that contains data","The maximum value in the sheet","The number of sheets in the workbook"],"answer":1,"why":"max_row is the index of the last non-empty row."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"import openpyxl\nwb = openpyxl.Workbook()\nws = wb.active\nws.append([\"Name\", \"Score\"])\nws.append([\"Al\", 85])\nprint(ws[\"B2\"].value)","options":["Al","0","Error","85"],"answer":3,"hint":"Row 1 is the header, so Al lands in row 2 and 85 in column B."}},{"id":"a74","section":"launch-pad","track":"advanced","title":"Automation: Sending Emails with Python","explain":"Python can send email with smtplib and build messages with the email.message module: set the subject, sender and recipient, add a plain-text body, and the message is ready to hand to a mail server. Never hard-code your real password — use an app password from an environment variable.","takeaways":["`EmailMessage()` builds a message; set `msg[\"Subject\"]`, `msg[\"From\"]` and `msg[\"To\"]` like a dictionary.","`msg.set_content(\"...\")` adds the plain-text body of the email.","Send with `smtplib.SMTP_SSL(\"smtp.gmail.com\", 465)` and log in with an app password, never your main password."],"code":"from email.message import EmailMessage\n\nmsg = EmailMessage()\nmsg[\"Subject\"] = \"Your Skillzify progress\"\nmsg[\"From\"] = \"hello@skillzify.example\"\nmsg[\"To\"] = \"ava@example.com\"\nmsg.set_content(\"Hi Ava, you finished 3 lessons this week!\")\nprint(msg[\"Subject\"])\nprint(msg[\"To\"])\nprint(\"Hi Ava\" in msg.get_content())","quiz":[{"q":"What does msg.set_content('Hello!') do?","options":["Sends the email immediately","Adds an attachment to the email","Sets the plain-text body of the email","Sets the email subject line"],"answer":2,"why":"set_content writes the message body; sending is a separate smtplib step."},{"q":"Why should you use an app password instead of your main Gmail password in a script?","options":["So a leaked script password cannot unlock your whole account and can be revoked alone","App passwords make emails send faster","Gmail blocks all other passwords","App passwords are shorter to type"],"answer":0,"why":"An app password is scoped to one use and revocable without changing your real password."},{"q":"Which module actually delivers the message to a mail server?","options":["os","json","smtplib","email.message"],"answer":2,"why":"email.message builds the message; smtplib speaks SMTP to send it."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"from email.message import EmailMessage\nmsg = EmailMessage()\nmsg[\"From\"] = \"bot@skillzify.example\"\nmsg[\"To\"] = \"bo@example.com\"\nmsg.set_content(\"Reminder: quiz at 6 pm.\")\nprint(msg[\"From\"], msg[\"To\"])","options":["bot@skillzify.example bo@example.com","bo@example.com bot@skillzify.example","Reminder: quiz at 6 pm.","Error"],"answer":0,"hint":"Headers print in the order you ask for them."}},{"id":"a75","section":"launch-pad","track":"advanced","title":"Automation: Scheduling Tasks","explain":"A scheduled task runs on its own: a daily backup, a weekly report, a reminder every morning. Inside Python, the sched module runs functions after a delay, while real deployments use cron on Linux or Task Scheduler on Windows for jobs that must survive restarts.","takeaways":["`sched.scheduler(time.time, time.sleep)` runs functions after a delay you choose.","`scheduler.enter(60, 1, job)` schedules job to run in 60 seconds; `scheduler.run()` starts the loop.","For jobs that must run even when your script is closed, use cron (Linux) or Task Scheduler (Windows)."],"code":"import sched, time\n\ndone = []\ns = sched.scheduler(time.time, time.sleep)\ns.enter(0.05, 1, done.append, argument=(\"backup done\",))\ns.run()\nprint(done)","quiz":[{"q":"What does scheduler.enter(60, 1, job) do?","options":["Runs job 60 times immediately","Pauses the program for 60 minutes","Cancels a job named job","Schedules job to run after 60 seconds"],"answer":3,"why":"enter takes a delay in seconds, a priority, and the function to call."},{"q":"What does scheduler.run() do?","options":["Runs the job once per second forever","Starts the loop that waits and executes scheduled jobs","Lists all scheduled jobs","Deletes every scheduled job"],"answer":1,"why":"run blocks and fires each job when its time arrives."},{"q":"Why use cron instead of sched for a daily 6 am backup?","options":["cron is written in Python","sched cannot run daily jobs","cron sends the backup by email automatically","cron runs even when your Python script is not running"],"answer":3,"why":"sched only works while your process is alive; cron is the operating system scheduler."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"import sched, time\nlog = []\ns = sched.scheduler(time.time, time.sleep)\ns.enter(0.01, 1, log.append, argument=(\"a\",))\ns.enter(0.01, 2, log.append, argument=(\"b\",))\ns.run()\nprint(log)","options":["[]","Error","['a', 'b']","['b', 'a']"],"answer":2,"hint":"Same delay, so the lower priority number runs first."}},{"id":"a82","section":"launch-pad","track":"advanced","title":"Git for Python Devs: A Practical Workflow","explain":"Git is how real Python projects stay sane: a branch per feature, small commits with clear messages, and pull requests for review. The daily loop is pull, branch, commit, push, and open a pull request — never commit straight to main.","takeaways":["`git pull` first, so your branch starts from the latest main.","One branch per feature (`feature/login-fix`); small commits with messages like `Add login validation`.","Never force-push shared branches; merge or rebase, then open a pull request for review."],"code":"import subprocess\n\nresult = subprocess.run([\"git\", \"--version\"], capture_output=True, text=True)\nprint(result.stdout.strip())\nprint(\"branch: feature/add-lesson\")\nprint(\"main is protected: push via pull request\")","quiz":[{"q":"Why pull before starting new work?","options":["It is required by Python","It makes commits smaller","So your branch starts from the latest main and avoids needless conflicts","Pulling deletes your local changes"],"answer":2,"why":"Working from stale main guarantees merge conflicts later."},{"q":"What is a pull request for?","options":["Proposing a branch for review before it merges into main","Downloading a repository","Deleting a branch","Backing up your files"],"answer":0,"why":"A pull request is the review gate: discussion, tests, and approval before merging."},{"q":"Why should you avoid force-pushing a shared branch?","options":["It deletes the remote repository","It only works on main","It rewrites history other people have already based work on","It is slower than a normal push"],"answer":2,"why":"Force-push can strand teammates' commits; it is safe only on your own private branch."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"import re\nprint(bool(re.fullmatch(r\"[a-z0-9/-]+\", \"feature/login-fix\")))","options":["feature","Error","True","False"],"answer":2,"hint":"Every character in the branch name is a lowercase letter, digit, slash, or hyphen."}},{"id":"a83","section":"launch-pad","track":"advanced","title":"Capstone: REST API with Flask & SQLite","explain":"This capstone ties it together: a Flask REST API backed by SQLite. Routes return JSON, POST adds a note, GET lists them — and you test it all with Flask's built-in test client, no server needed.","takeaways":["`app.test_client()` exercises routes in-process: no server, no network, instant tests.","Return JSON with `jsonify(...)` and the right status code (201 for a created resource).","`request.get_json()` reads the JSON body a client POSTed."],"code":"from flask import Flask, jsonify, request\n\napp = Flask(__name__)\nnotes = []\n\n@app.route(\"/notes\", methods=[\"GET\"])\ndef list_notes():\n    return jsonify(notes)\n\n@app.route(\"/notes\", methods=[\"POST\"])\ndef add_note():\n    notes.append(request.get_json()[\"text\"])\n    return jsonify({\"added\": notes[-1]}), 201\n\nclient = app.test_client()\nprint(client.post(\"/notes\", json={\"text\": \"Learn Flask\"}).status_code)\nprint(client.get(\"/notes\").get_json())","quiz":[{"q":"What does app.test_client() give you?","options":["A real web browser","A production server","A database connection","A way to call your routes in-process without starting a server"],"answer":3,"why":"The test client simulates HTTP requests directly against the app object."},{"q":"Which status code should a successful POST that creates a resource return?","options":["500","201","200","404"],"answer":1,"why":"201 Created is the standard code for a newly created resource."},{"q":"How do you read JSON a client sent in a POST body?","options":["request.args['text']","json.loads(app)","flask.read_json()","request.get_json()"],"answer":3,"why":"get_json parses the request body into a Python dict."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"from flask import Flask, jsonify\napp = Flask(__name__)\n\n@app.route(\"/ping\")\ndef ping():\n    return jsonify({\"status\": \"ok\"})\n\nclient = app.test_client()\nprint(client.get(\"/ping\").status_code)\nprint(client.get(\"/ping\").get_json())","options":["404\n{}","200\nok","Error","200\n{'status': 'ok'}"],"answer":3,"hint":"The route exists, and jsonify turns the dict into a JSON response.","localOnly":true}},{"id":"a85","section":"launch-pad","track":"advanced","title":"Capstone: Full-Stack Mini App","explain":"A full-stack mini app is a small web app end to end: Flask serves a page, the page is rendered from a template, and the test client proves it works. The pattern is the same one big apps use — routes, templates, data — just smaller.","takeaways":["`render_template_string(\"<h1>{{ title }}</h1>\", title=\"...\")` renders a template from a string.","Routes return HTML for browsers and JSON for APIs; one Flask app can serve both.","Test the rendered page with `client.get(\"/\")` and check the status code and body."],"code":"from flask import Flask, render_template_string\n\napp = Flask(__name__)\n\n@app.route(\"/\")\ndef home():\n    return render_template_string(\"<h1>{{ title }}</h1>\", title=\"Skillzify\")\n\nclient = app.test_client()\nresp = client.get(\"/\")\nprint(resp.status_code)\nprint(b\"Skillzify\" in resp.data)","quiz":[{"q":"What does render_template_string do?","options":["Starts the Flask server","Renders a Jinja template given as a string, filling in the variables","Reads a template file from disk","Sends an email"],"answer":1,"why":"It takes the template text directly instead of loading a file."},{"q":"In a Flask app, what is the difference between a route returning HTML and one returning JSON?","options":["HTML routes are faster","JSON routes need no test client","There is no difference","HTML is for browsers to display; JSON is data for other programs to consume"],"answer":3,"why":"Same routing, different payload: pages for people, JSON for clients."},{"q":"How do you check what a route actually returned in a test?","options":["Open a browser","resp.status_code and resp.data on the test client response","Print the Flask app object","Read the server log file"],"answer":1,"why":"The response object carries the status and the raw body bytes."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"from flask import Flask\napp = Flask(__name__)\n\n@app.route(\"/hello/<name>\")\ndef hello(name):\n    return \"Hello, \" + name + \"!\"\n\nclient = app.test_client()\nprint(client.get(\"/hello/Ava\").data.decode())","options":["Hello, name!","404","Error","Hello, Ava!"],"answer":3,"hint":"The <name> part of the URL is captured and passed to the function.","localOnly":true}},{"id":"a86","section":"launch-pad","track":"advanced","title":"Asyncio: Web Scraping at Scale","explain":"Scraping one page is easy; scraping a hundred pages one by one is slow, because each request mostly waits. asyncio lets hundreds of fetches wait at the same time, so the whole job finishes in roughly the time of the slowest single page.","takeaways":["`asyncio.gather(*tasks)` runs many coroutines concurrently and collects their results in order.","While one fetch awaits a response, the event loop runs the others — that is where the speedup comes from.","Always cap concurrency (a semaphore) and respect rate limits, or you will hammer the server."],"code":"import asyncio, re\n\npages = {\"page1\": \"<h1>Python</h1>\", \"page2\": \"<h1>Flask</h1>\", \"page3\": \"<h1>asyncio</h1>\"}\n\nasync def fetch(name, html):\n    await asyncio.sleep(0.01)\n    return re.search(r\"<h1>(.*?)</h1>\", html).group(1)\n\nasync def main():\n    titles = await asyncio.gather(*(fetch(n, h) for n, h in pages.items()))\n    print(titles)\n\nasyncio.run(main())","quiz":[{"q":"What does asyncio.gather(*tasks) do?","options":["Runs them on separate CPU cores","Cancels all but the first task","Runs the coroutines concurrently and returns their results in order","Runs them one by one in sequence"],"answer":2,"why":"gather schedules all tasks on the event loop and collects results in task order."},{"q":"Why is asyncio faster than a loop for scraping many pages?","options":["While one fetch waits for a response, others run instead of idling","It downloads pages at a higher bandwidth","It skips parsing the HTML","It uses multiple CPUs"],"answer":0,"why":"Network scraping is wait-bound; asyncio overlaps the waiting."},{"q":"Why cap concurrency with a semaphore when scraping at scale?","options":["asyncio requires one for every task","It reduces the HTML size","To avoid overwhelming the server and getting blocked","Semaphores make parsing faster"],"answer":2,"why":"Unbounded concurrency looks like an attack; polite scrapers limit in-flight requests."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"import asyncio\n\nasync def work(n):\n    await asyncio.sleep(0.01)\n    return n * 2\n\nasync def main():\n    print(await asyncio.gather(work(1), work(2)))\n\nasyncio.run(main())","options":["[2, 4]","[1, 2]","[4, 2]","Error"],"answer":0,"hint":"gather returns results in the order the tasks were given."}},{"id":"a88","section":"launch-pad","track":"advanced","title":"Web: Deploying a Flask App","explain":"Deploying means your Flask app runs on a server anyone can reach. The checklist is short: a production server like Gunicorn instead of the dev server, a PORT from the environment, a /health endpoint to prove the app is alive, and your secrets in environment variables — never in the code.","takeaways":["Never deploy with the Flask dev server; use a production server such as Gunicorn.","Read the port from the environment: `os.environ.get(\"PORT\", \"5000\")`.","Add a `/health` endpoint returning `{\"status\": \"ok\"}` so the platform can check the app is alive."],"code":"import os\nfrom flask import Flask\n\napp = Flask(__name__)\n\n@app.route(\"/health\")\ndef health():\n    return {\"status\": \"ok\"}\n\nclient = app.test_client()\nprint(client.get(\"/health\").status_code)\nprint(client.get(\"/health\").get_json())\nprint(\"port:\", os.environ.get(\"PORT\", \"5000\"))","quiz":[{"q":"Why not deploy with Flask's built-in development server?","options":["It is single-threaded, insecure, and not built for production traffic","It cannot serve JSON","It costs money","It only runs on Windows"],"answer":0,"why":"The dev server is a debugging convenience; production needs Gunicorn or similar."},{"q":"Why read PORT from the environment instead of hard-coding 5000?","options":["Port 5000 is banned in production","Flask requires it","The hosting platform assigns the port your app must listen on","Environment variables are faster"],"answer":2,"why":"Platforms like Render assign a port dynamically; hard-coding breaks the deploy."},{"q":"What is a /health endpoint for?","options":["Letting the platform and monitoring check the app is alive and responding","Showing users a status page","Logging users in","Backing up the database"],"answer":0,"why":"Health checks ping /health and restart or alert if it stops answering."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"from flask import Flask\napp = Flask(__name__)\n\n@app.route(\"/health\")\ndef health():\n    return {\"status\": \"ok\"}\n\nclient = app.test_client()\nprint(client.get(\"/health\").get_json()[\"status\"])","options":["ok","200","healthy","Error"],"answer":0,"hint":"get_json() gives a dict; take its status value.","localOnly":true}},{"id":"a90","section":"launch-pad","track":"advanced","title":"Capstone: Personal AI Assistant CLI","explain":"This capstone builds a tiny personal assistant as a command-line tool: argparse reads the command, a small rule-based brain picks the reply, and the whole thing runs from the terminal. It is the skeleton every bigger assistant starts from — commands in, answers out.","takeaways":["`argparse` turns `assistant remind` into a parsed command your code can act on.","A rule-based brain is just a dict of commands to replies — start simple, add rules as you go.","Keep the brain a pure function (`reply(task)`) so you can test it without the CLI."],"code":"import argparse\n\ndef reply(task):\n    answers = {\"remind\": \"Reminder set for 6 pm.\", \"joke\": \"Why do programmers prefer dark mode? Less light to debug.\"}\n    return answers.get(task, \"I can remind or joke - try one of those.\")\n\np = argparse.ArgumentParser()\np.add_argument(\"task\")\nargs = p.parse_args([\"remind\"])\nprint(reply(args.task))","quiz":[{"q":"Why keep the assistant brain as a pure function reply(task)?","options":["argparse requires it","It saves the replies to disk","So you can test it directly without going through the CLI","Pure functions run faster"],"answer":2,"why":"A pure function takes a string and returns a string — trivially testable."},{"q":"How does argparse know the user typed 'remind'?","options":["parse_args reads the command-line words into args.task","It scans the source code","It asks with input()","It reads an environment variable"],"answer":0,"why":"The positional argument 'task' captures the first word after the program name."},{"q":"What is the sensible next step after a rule-based assistant works?","options":["Rewrite it in another language","Remove argparse","Add more commands, then swap the brain for a real model API when needed","Delete the rules immediately"],"answer":2,"why":"Grow the command set first; an LLM backend slots into the same reply() shape later."}],"challenge":{"type":"predict","prompt":"What will this print?","code":"import argparse\n\ndef reply(task):\n    answers = {\"remind\": \"Reminder set for 6 pm.\", \"joke\": \"Why do programmers prefer dark mode? Less light to debug.\"}\n    return answers.get(task, \"I can remind or joke - try one of those.\")\n\np = argparse.ArgumentParser()\np.add_argument(\"task\")\nargs = p.parse_args([\"joke\"])\nprint(reply(args.task))","options":["Reminder set for 6 pm.","I can remind or joke - try one of those.","Error","Why do programmers prefer dark mode? Less light to debug."],"answer":3,"hint":"The joke key maps to the joke string."}}];
